    except PointerError:
        pass

# validate + project
paths, toks = jp.validate_paths(["/role", "/addr/city"], claims)
assert paths == ["/role", "/addr/city"]
assert jp.project(claims, toks) == {"role": "admin", "addr": {"city": "BJ"}}, jp.project(claims, toks)

# 零披露
assert jp.validate_paths([], claims) == ([], [])
assert jp.project(claims, []) == {}

# 命中数组整体值可以，进数组索引不行
p, t = jp.validate_paths(["/tags"], claims)
assert jp.project(claims, t) == {"tags": [1, 2]}
for bad in ["/tags/0", "/missing", "/addr/nope", "/addr/city/x"]:
    try:
        jp.validate_paths([bad], claims); raise AssertionError(f"应拒绝 {bad}")
    except PointerError:
        pass

# 非数组 disclose
for bad in [None, "/role", {"a": 1}, 42]:
    try:
        jp.validate_paths(bad, claims); raise AssertionError("应拒绝")
    except PointerError:
        pass

# 重复（语义相同，转义不同写法也算重复）
for bad in [["/role", "/role"], ["/a~1b", "/a/b"]]:
